WITH LAST_DECISION AS ( SELECT d.*, ROW_NUMBER() OVER (PARTITION BY d.APPLICATION_ID ORDER BY d.DECISION_DATE DESC, d.DECISION_ID DESC) RN FROM MFF_CREDIT_DECISIONS d ), LAST_INQUIRY AS ( SELECT q.*, ROW_NUMBER() OVER (PARTITION BY q.APPLICATION_ID ORDER BY q.RESPONSE_DATE DESC NULLS LAST, q.INQUIRY_ID DESC) RN FROM MFF_CREDIT_INQUIRIES q ) SELECT a.APPLICATION_ID, a.APPLICATION_NO, a.APPLICATION_DATE, a.STATUS_CODE, s.NAME_AR STATUS_NAME_AR, p.PERSON_ID, p.FULL_NAME_AR APPLICANT_NAME_AR, p.NATIONAL_ID, p.MARITAL_STATUS_CODE, p.EMPLOYMENT_TYPE_CODE, a.MONTHLY_INCOME_TOTAL, a.PROPERTY_PRICE, a.DOWNPAYMENT_AMOUNT, a.REQUESTED_FINANCE_AMOUNT, a.APPROVED_FINANCE_AMOUNT, a.TOTAL_SUBSIDY_AMOUNT, f.ORG_ID FINANCIER_ID, f.ORG_NAME_AR FINANCIER_NAME_AR, f.ORG_TYPE_CODE FINANCIER_TYPE_CODE, f.REGULATOR_CODE, fund.ORG_NAME_AR FUND_NAME_AR, pv.PROGRAM_CODE, pv.VERSION_NO PROGRAM_VERSION_NO, hp.PROJECT_NAME_AR, pr.GOVERNORATE_CODE, pr.CITY_CODE, pr.AREA_SQM, pr.SALE_PRICE, pr.APPRAISED_VALUE, ld.DECISION_CODE LAST_DECISION_CODE, ld.DECISION_DATE LAST_DECISION_DATE, li.CREDIT_SCORE LAST_CREDIT_SCORE, li.RESULT_CODE LAST_CREDIT_INQUIRY_RESULT, a.CURRENT_OWNER_USER, a.BRANCH_CODE FROM MFF_APPLICATIONS a JOIN MFF_PERSONS p ON p.PERSON_ID = a.PRIMARY_PERSON_ID JOIN MFF_ORGANIZATIONS f ON f.ORG_ID = a.FINANCIER_ID JOIN MFF_ORGANIZATIONS fund ON fund.ORG_ID = a.FUND_ORG_ID JOIN MFF_PROGRAM_VERSIONS pv ON pv.PROGRAM_VERSION_ID = a.PROGRAM_VERSION_ID JOIN REF_MFF_APPLICATION_STATUS s ON s.CODE = a.STATUS_CODE LEFT JOIN MFF_APPLICATION_PROPERTY ap ON ap.APPLICATION_ID = a.APPLICATION_ID AND ap.SELECTED_FLAG = 'Y' LEFT JOIN MFF_PROPERTIES pr ON pr.PROPERTY_ID = ap.PROPERTY_ID LEFT JOIN MFF_HOUSING_PROJECTS hp ON hp.PROJECT_ID = pr.PROJECT_ID LEFT JOIN LAST_DECISION ld ON ld.APPLICATION_ID = a.APPLICATION_ID AND ld.RN = 1 LEFT JOIN LAST_INQUIRY li ON li.APPLICATION_ID = a.APPLICATION_ID AND li.RN = 1;
